package main

import (
	"encoding/json"
	"fmt"
	"reflect"
	"strings"
	"unicode"

	dynamicstruct "github.com/gosmos-space/dynamicstruct"
)

func main() {

	// Paste the JSON generated by json-generator.com here.
	jsonData := `{
		"name": "John Doe",
		"age": 30,
		"address": {
			"city": "Mumbai",
			"pincode": 400001
		},
		"hobbies": [
			"coding",
			"music"
		],
		"friends": [
			{
				"name": "Alex",
				"age": 25
			},
			{
				"name": "Sam",
				"age": 28
			}
		]
	}`

	var data map[string]interface{}

	err := json.Unmarshal([]byte(jsonData), &data)
	if err != nil {
		fmt.Println(err)
		return
	}

	structValue, err := createDynamicStruct(data)
	if err != nil {
		fmt.Println(err)
		return
	}

	// Convert the generated struct to a string.
	structString := fmt.Sprintf("%+v", structValue)

	fmt.Println(structString)
}

func createDynamicStruct(data map[string]interface{}) (interface{}, error) {

	builder := dynamicstruct.New()

	for field, value := range data {

		fieldName := toStructFieldName(field)

		dynamicValue, err := createDynamicValue(value)
		if err != nil {
			return nil, err
		}

		builder.AddField(
			fieldName,
			dynamicValue,
			`json:"`+field+`"`,
		)
	}

	instance, err := builder.Build()
	if err != nil {
		return nil, err
	}

	// Create a pointer to the generated struct.
	structPtr := reflect.New(reflect.TypeOf(instance)).Interface()

	// Populate the generated struct using the original JSON data.
	jsonData, err := json.Marshal(data)
	if err != nil {
		return nil, err
	}

	err = json.Unmarshal(jsonData, structPtr)
	if err != nil {
		return nil, err
	}

	return reflect.ValueOf(structPtr).Elem().Interface(), nil
}

func createDynamicValue(value interface{}) (interface{}, error) {

	switch value := value.(type) {

	case map[string]interface{}:
		// Nested JSON object.
		return createDynamicStruct(value)

	case []interface{}:
		// JSON array.
		if len(value) == 0 {
			return []interface{}{}, nil
		}

		values := make([]interface{}, len(value))

		for i, item := range value {
			dynamicValue, err := createDynamicValue(item)
			if err != nil {
				return nil, err
			}

			values[i] = dynamicValue
		}

		// Create a slice using the type of the first element.
		elementType := reflect.TypeOf(values[0])

		slice := reflect.MakeSlice(
			reflect.SliceOf(elementType),
			len(values),
			len(values),
		)

		for i, value := range values {
			slice.Index(i).Set(reflect.ValueOf(value))
		}

		return slice.Interface(), nil

	default:
		// string, float64, bool, nil, etc.
		return value, nil
	}
}

func toStructFieldName(field string) string {

	fieldName := strings.Map(func(r rune) rune {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			return r
		}

		return -1
	}, field)

	if fieldName == "" {
		return "Field"
	}

	return strings.ToUpper(fieldName[:1]) + fieldName[1:]
}

